module rtl_h_fix_i2c_clk_stall(
    input  wire clk,
    input  wire rst_n,
    input  wire enable,
    output wire scl_out,
    output reg  [1:0] clk_cnt
);
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            clk_cnt <= 2'b00;
        end else if (enable) begin
            clk_cnt <= clk_cnt + 1'b1;
        end
    end

    // BUG: SCL only high on count 3
    assign scl_out = (clk_cnt == 2'b11);

endmodule

module rtl_h_fix_sub_overflow(
    input  wire [7:0] a,
    input  wire [7:0] b,
    output wire [7:0] diff,
    output wire       overflow
);
    assign diff = a - b;
    // BUG: uses addition overflow condition instead of subtraction
    assign overflow = (a[7] == b[7]) && (diff[7] != a[7]);

endmodule

