module rtl_h_fix_encoder_wrap(
    input  wire       clk,
    input  wire       rst_n,
    input  wire       fwd_pulse,
    input  wire       clear_sample,
    output reg  [7:0] speed_acc,
    output wire       saturated
);
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            speed_acc <= 8'd0;
        end else if (clear_sample) begin
            speed_acc <= 8'd0;
        end else if (fwd_pulse) begin
            // BUG: natural rollover wrap at 255
            speed_acc <= speed_acc + 1'b1;
        end
    end

    assign saturated = (speed_acc == 8'hFF);

endmodule

module rtl_h_fix_bidir_latch(
    input  wire       oe_n,
    input  wire       dir,
    input  wire [7:0] data_a,
    input  wire [7:0] data_b,
    output wire [7:0] out_a,
    output wire [7:0] out_b,
    output wire       a_driven,
    output wire       b_driven
);
    // BUG: active-high check instead of active-low oe_n
    assign b_driven = oe_n && dir;
    assign a_driven = oe_n && !dir;
    assign out_b    = b_driven ? data_a : 8'd0;
    assign out_a    = a_driven ? data_b : 8'd0;

endmodule

