module rtl_h_fix_i2c_ack(
    input  wire sda_in,
    input  wire ack_sample_en,
    output wire ack_received,
    output wire nack_received
);
    // BUG: inverted acknowledge polarity
    assign ack_received  = ack_sample_en && sda_in;
    assign nack_received = ack_sample_en && !sda_in;

endmodule

module rtl_h_fix_arb_deassert(
    input  wire clk,
    input  wire rst_n,
    input  wire req0,
    input  wire req1,
    output reg  grant0,
    output reg  grant1
);
    // BUG: does not clear grant0 when req0 falls
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            grant0 <= 1'b0;
            grant1 <= 1'b0;
        end else if (req0) begin
            grant0 <= 1'b1;
            grant1 <= 1'b0;
        end else if (req1 && !grant0) begin // BUG: grant0 never cleared
            grant1 <= 1'b1;
        end
    end

endmodule

